const mongoose = require("mongoose");

const userSchema = new mongoose.Schema({
    fullname:{
        type:String,
        required:true
    },

    email:{
        type:String,
        required:true,
    },

    phone:{
        type:String,
        required:true,
    },

    age:{
        type:Number,
        required:true
    },

    bloodGroup:{
        type:String,
        required:true
    },

    city:{
        type:String,
        required:true
    },

    password:{
        type:String,
        required:true
    },
    role: {
        type: String,
        enum: ["donor", "admin"],
        default: "donor"
    }


},{timestamps:true});

module.exports = mongoose.model("User",userSchema);